import React, { createContext, useContext, useState, useEffect } from 'react';

const CheckoutContext = createContext();

export const CheckoutProvider = ({ children }) => {
    // 1. Unified Checkout State
    const [shippingData, setShippingData] = useState(() => {
        const saved = localStorage.getItem('bindass_checkout_shipping');
        return saved ? JSON.parse(saved) : {
            firstName: '',
            lastName: '',
            addressLine1: '',
            city: '',
            state: '',
            pincode: '',
            countryCode: 'IN',
            email: '',
            phone: ''
        };
    });

    const [appliedCoupon, setAppliedCoupon] = useState(() => {
        const saved = localStorage.getItem('bindass_applied_coupon');
        return saved ? JSON.parse(saved) : null;
    });

    const [paymentData, setPaymentData] = useState(() => {
        const saved = localStorage.getItem('bindass_checkout_payment');
        return saved ? JSON.parse(saved) : { method: 'card', lastFour: 'XXXX' };
    });

    const [checkoutTotals, setCheckoutTotals] = useState(() => {
        const saved = localStorage.getItem('bindass_checkout_totals');
        try {
            const parsed = saved ? JSON.parse(saved) : null;
            return parsed || { subtotal: 0, tax: 0, discount: 0, totalAmount: 0 };
        } catch (e) {
            return { subtotal: 0, tax: 0, discount: 0, totalAmount: 0 };
        }
    });

    // 2. Persistence Layer
    useEffect(() => {
        localStorage.setItem('bindass_checkout_shipping', JSON.stringify(shippingData));
    }, [shippingData]);

    useEffect(() => {
        localStorage.setItem('bindass_checkout_payment', JSON.stringify(paymentData));
    }, [paymentData]);

    useEffect(() => {
        localStorage.setItem('bindass_applied_coupon', JSON.stringify(appliedCoupon));
    }, [appliedCoupon]);

    useEffect(() => {
        localStorage.setItem('bindass_checkout_totals', JSON.stringify(checkoutTotals));
    }, [checkoutTotals]);

    // 3. Actions
    const updateShipping = (data) => setShippingData(prev => ({ ...prev, ...data }));
    const updatePayment = (data) => setPaymentData(prev => ({ ...prev, ...data }));

    const applyCoupon = (coupon) => {
        setAppliedCoupon(coupon);
        // We'll let the component that calls updateTotals pass the new discount
    };

    const removeCoupon = () => {
        setAppliedCoupon(null);
        // Recalculate totals in the calling component
    };

    const updateTotals = (data) => {
        setCheckoutTotals(prev => {
            const subtotal = Number(data.subtotal ?? prev.subtotal ?? 0);
            const discount = Number(data.discount ?? prev.discount ?? 0);
            const taxRate = 0.08; // 8% Luxury Tax

            const discountedSubtotal = Math.max(0, subtotal - discount);
            const tax = Math.round(discountedSubtotal * taxRate);
            const totalAmount = discountedSubtotal + tax;

            return { subtotal, tax, discount, totalAmount };
        });
    };

    const clearCheckout = () => {
        localStorage.removeItem('bindass_checkout_shipping');
        localStorage.removeItem('bindass_checkout_payment');
        localStorage.removeItem('bindass_checkout_totals');
        localStorage.removeItem('bindass_applied_coupon');
        setShippingData({
            firstName: '',
            lastName: '',
            addressLine1: '',
            city: '',
            state: '',
            pincode: '',
            countryCode: 'IN',
            email: '',
            phone: ''
        });
        setPaymentData({ method: 'card', lastFour: 'XXXX' });
        setAppliedCoupon(null);
        setCheckoutTotals({ subtotal: 0, tax: 0, discount: 0, totalAmount: 0 });
    };

    return (
        <CheckoutContext.Provider value={{ 
            shippingData, updateShipping, 
            paymentData, updatePayment, 
            checkoutTotals, updateTotals,
            appliedCoupon, applyCoupon, removeCoupon,
            clearCheckout 
        }}>
            {children}
        </CheckoutContext.Provider>
    );
};

export const useCheckout = () => {
    const context = useContext(CheckoutContext);
    if (!context) {
        throw new Error('useCheckout must be used within a CheckoutProvider');
    }
    return context;
};
